# Exercises the built-in type fast paths; golden generated by CPython.
def show(f):
    try:
        print(repr(f()))
    except Exception as e:
        print(type(e).__name__, e)

STRS = ["", "a", "hello world", "a,b,,c", "héllo wörld", "日本語,テスト", "ç", "x\u0131y"]
for s in STRS:
    print(len(s), s.upper(), s.lower(), s.count("l"), s.count(""), s.find("o"), s.find(""))
    for i in (0, 1, -1, -2, 5, -9):
        show(lambda: s[i])
    for sl in (slice(1, 3), slice(-3, None), slice(None, None, 2), slice(None, None, -1), slice(2, 1)):
        show(lambda: s[sl])
    show(lambda: s.replace("l", "LL"))
    show(lambda: s.replace("", "-"))
    show(lambda: s.replace("", "-", 2))
    show(lambda: s.replace("l", "", 1))
    show(lambda: s.split(","))
    show(lambda: s.split(",", 1))
    show(lambda: s.split())
    show(lambda: s.split(""))
    show(lambda: s.rsplit(",", 1))
    show(lambda: s.partition("o"))
    show(lambda: ",".join([s, s]))
    show(lambda: s.count("l", 1, -1))
    show(lambda: s.find("l", -3))
    show(lambda: s.rfind("l"))
    show(lambda: s.index("zz"))
    show(lambda: s.startswith(("h", "")))
    show(lambda: s.center(15, "*"))
    show(lambda: s.ljust(12, "é"))
    show(lambda: s.zfill(14))
    show(lambda: s.title())
    show(lambda: s.capitalize())
    show(lambda: s.swapcase())
    show(lambda: s * 3)
    show(lambda: f"{s:>14}|{s:<14}|{s:^14}|{s:*^15}|{s:.3}|{s:é>9.2}")
show(lambda: ",".join(str(i) for i in range(5)))
show(lambda: "".join(["a", 1]))
show(lambda: ",".join(("é", "日")))

SPECS = ["", "d", "5d", "05d", "<5d", ">5d", "^7d", "*^7d", "+d", " d", "-d", "+05d", "=+6d", "x", "#x", "#X", "#o", "#b",
         "b", "o", "X", "08b", "#010x", ",", "_", ",d", "_d", "_x", "_b", "010,", "012_", "08,d", "c", "e", "E", ".2e", "#.0e",
         "f", ".0f", "#.0f", ".3f", "10.2f", "010.2f", "+.1f", ",.2f", "_.3f", "g", ".3g", "#g", "#.3g", "G", "%", ".1%", "n",
         "5", "z", ",x", "_n", ".2d", "s", "10x5", ",_d", "__d", "é>5d", "<<5", "=5", "00", "05", "5.", ".", "99999999999999999999"]
VALS = [0, 1, -1, 7, 255, -255, 1234567, -1234567, 2**40, 2**70, -2**70, True, False,
        0.0, -0.0, 1.5, -2.5, 0.5, 1e-5, 123456789.123456, 1e16, 1e22, 1.0e100, 0.1, 2.675, 1234567.891,
        float("inf"), float("-inf"), float("nan")]
for v in VALS:
    for sp in SPECS:
        show(lambda: format(v, sp))
for v in ["abc", "日本"]:
    for sp in ["", "5", ">5", "^6", "<6", "*>6", ".1", "5.1", "s", "d", "+", "=5", "#", ",", "_", "05", "x" ]:
        show(lambda: format(v, sp))
show(lambda: format(65, "c"))
show(lambda: format(-1, "c"))
show(lambda: format(65, "+c"))
show(lambda: "{:>4} {!r:>6} {:,}".format(1, "é", 10**9))
x = 42
show(lambda: f"{x:#06x} {x!r} {x=} {x:{x}}")

# floats
for v in [0.1, 1/3, 1e16, 1e-7, 123456789012345678.0, 5e-324, -0.0, 100.0, 2.5, 1e15]:
    print(repr(v), str(v), round(v), round(v, 2), round(v, -1) if abs(v) < 1e300 else 0)
for v in [0.5, 1.5, 2.5, -0.5, -1.5, 2.675, 0.125, 0.375]:
    print(round(v), round(v, 1), round(v, 2))
print(round(float("inf"), 2), round(float("nan"), 2))
print(2.0 ** 0.5, 2 ** -1, 10 ** 15 / 3, 7 / 2, -7 // 2.0, -7 % 2.5, 2.0 ** 1000)
print(float("inf") - float("inf"), -float("inf"), float("inf") > 1e308)
print([i ** 0.5 for i in range(1, 6)], 1e300 * 1e10, int(1e20), float(10**30), 2**53 + 0.0)

# bigint
a, b = 0, 1
for _ in range(500):
    a, b = b, a + b
print(a, len(str(a)), str(-a)[:20], hex(a)[:20], 3 ** 2000 % 1_000_003, pow(7, 123456, 10**9 + 7))
print(2**64, -2**64, 2**63 - 1, -2**63, 2**63, str(10**30), repr(-10**30))
print(divmod(-10**30, 7), (10**30) // -7, (10**30) % -7, -(10**30) >> 3, 1 << 100)
print(int("9" * 40), int("-" + "9" * 40) + 1, 10**40 // 10**20, (2**100) ** 2, 2 ** 100 == 2.0 ** 100)
show(lambda: str(2**100) + "x")
show(lambda: 10**5000 // 0)

# dicts
d = {}
for i in range(20):
    d[f"k{i % 7}"] = d.get(f"k{i % 7}", 0) + i
print(d, list(d.items())[:3], d.get("zz"), d.get("zz", 5), d.pop("k1"), d)
del d["k0"]
d["k0"] = "again"; d["k1"] = "back"
print(list(d), list(d.values()), len(d))
d2 = {"é": 1, "日本": 2, 1: 3, (1, 2): 6, None: 7}
print(d2, d2["é"], d2[1], (1, 2) in d2, "日本" in d2)
show(lambda: d2["nope"])
d3 = dict.fromkeys("héllo", 0)
d3.update(a=1, b=2)
d3.setdefault("é", 9); d3.setdefault("zz", 9)
print(d3, sorted(d3), {k: v for k, v in d3.items() if v})
for k in list(d3):
    del d3[k]
    d3[k] = 1
print(d3, d3.popitem(), d3)
show(lambda: {}.popitem())
show(lambda: {}.pop("a"))

# json
import json
data = [{"id": i, "name": f"n{i}é", "tags": ["a", "日"], "v": i / 3, "n": None, "t": True} for i in range(3)]
s = json.dumps(data)
print(s)
print(json.dumps({"b": 1, "a": [1.5, 1e100, -0.0]}, sort_keys=True))
print(json.dumps(data[:1], indent=2))
B = chr(92)
print(json.loads(s) == data, json.loads('"' + B + 'u00e9' + B + 'ud83d' + B + 'ude00' + B + 'n"'), json.loads(' [1, 2.5e3, -0, {"a": []}] '))
print(json.dumps("quote" + chr(34) + B + "\n\t\x01é\U0001F600"), json.dumps(float("inf")), json.dumps({1: 2, 1.5: 3, True: 5}))
show(lambda: json.dumps({(1, 2): 3}))

# exceptions
n = 0
for i in range(5):
    try:
        if i % 2: raise ValueError(i)
    except ValueError as e:
        n += e.args[0]
        print(e, repr(e), e.args, str(e))
print(n, ValueError(), ValueError(1, 2), repr(KeyError("k")), str(KeyError("k")))
show(lambda: int("x"))
show(lambda: [][1])
show(lambda: {}["k"])
